class Card {
    String face;
    Card(String f) { face = f; }
    public String toString() { return face; }
}
public class Test {
    public static void main(String[] args) {
        Card[] deck = new Card[2];
        deck[0] = new Card("Ace");
        try {
            System.out.printf("%s %s", deck[0], deck[1].toString());
        } catch (NullPointerException e) {
            System.out.print("NPE ");
        }
        System.out.printf("%03d", deck.length);
    }
}
